class Person { String name = "Anna"; }
public static void main(String[] args) {
  Person p = new Person();
  System.out.print(p.name);
}

class Car {
  String brand;
  Car(String b) { brand = b; }
}
public static void main(String[] args) {
  Car c = new Car("BMW");
  System.out.print(c.brand);
}

class A { void f() { System.out.print("A"); } }
class B extends A { void f() { System.out.print("B"); } }
public static void main(String[] args) {
  A obj = new B();
  obj.f();
}

class Counter {
  static int count = 0;
  Counter() { count++; }
}
public static void main(String[] args) {
  new Counter();
  new Counter();
  System.out.print(Counter.count);
}

class MyClass { void test() { System.out.print("OK"); } }
public static void main(String[] args) {
  MyClass m = null;
  try {
    m.test();
  } catch (NullPointerException e) {
    System.out.print("ERROR");
  }
}
